<section class="panel"><h2>새 문의 접수</h2><form method="post" action="/admin/support" class="form-grid"><input type="hidden" name="_token" value="<?= View::e(Csrf::token()) ?>"><label>유형<select name="ticket_type" required><?php foreach(['question'=>'사용 문의','error'=>'오류 신고','feature'=>'추가 기능 요청'] as $value=>$label): ?><option value="<?= $value ?>" <?= ($old['ticket_type']??'question')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>중요도<select name="priority" required><?php foreach(['normal'=>'일반','high'=>'높음','urgent'=>'긴급'] as $value=>$label): ?><option value="<?= $value ?>" <?= ($old['priority']??'normal')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label class="full">제목<input name="subject" required minlength="2" maxlength="190" value="<?= $v('subject') ?>"></label><label class="full">내용<textarea name="body" required minlength="10" maxlength="10000" rows="7"><?= $v('body') ?></textarea></label><label class="full">관련 화면 주소(HTTPS)<input type="url" name="related_url" maxlength="500" value="<?= $v('related_url') ?>" placeholder="https://..."></label><label>오류 발생 시간<input type="datetime-local" name="occurred_at" value="<?= $v('occurred_at') ?>"></label><button class="button primary" type="submit">문의 접수</button></form></section>
<section class="panel"><h2>문의 이력</h2><div class="table-wrap"><table><thead><tr><th>번호</th><th>유형·중요도</th><th>제목</th><th>상태</th><th>접수일</th><th>답변 요약</th></tr></thead><tbody><?php $types=['question'=>'문의','error'=>'오류','feature'=>'기능'];$priorities=['normal'=>'일반','high'=>'높음','urgent'=>'긴급'];$statuses=['open'=>'접수','in_progress'=>'처리 중','answered'=>'답변 완료','closed'=>'종료']; foreach($tickets as $ticket): ?><tr><td>#<?= (int)$ticket['id'] ?></td><td><?= View::e($types[$ticket['ticket_type']]??$ticket['ticket_type']) ?> · <?= View::e($priorities[$ticket['priority']]??$ticket['priority']) ?></td><td><?= View::e($ticket['subject']) ?></td><td><?= View::e($statuses[$ticket['status']]??$ticket['status']) ?></td><td><?= View::e($ticket['created_at']) ?></td><td><?= View::e($ticket['response_summary']??'-') ?></td></tr><?php endforeach; ?><?php if($tickets===[]): ?><tr><td colspan="6" class="empty">접수한 문의가 없습니다.</td></tr><?php endif; ?></tbody></table></div></section>
